const withoutIds = (value: unknown): unknown => Array.isArray(value) ? value.map(withoutIds)
  : value && typeof value === 'object' ? Object.fromEntries(Object.entries(value).filter(([key]) => key !== 'id').map(([key, item]) => [key, withoutIds(item)]))
  : value
const same = (a: unknown, b: unknown) => JSON.stringify(withoutIds(a)) === JSON.stringify(withoutIds(b))

export function applyBrandRedesign(doc: Record<string, unknown>, direction: 'up' | 'down'): number {
  let applied = 0
  for (const change of changes) {
    const [from, to] = direction === 'up' ? [change.from, change.to] : [change.to, change.from]
    const parent = change.path.slice(0, -1).reduce<any>((node, key) => node?.[key], doc)
    const key = change.path[change.path.length - 1]
    if (!parent || typeof parent !== 'object' || !same(parent[key], from)) continue
    parent[key] = structuredClone(to)
    applied++
  }
  return applied
}

async function migrate({ payload, req }: MigrateUpArgs, direction: 'up' | 'down') {
  const published = await payload.findGlobal({ slug: 'landing', draft: false, depth: 0, req }) as unknown as Record<string, unknown>
  if (published._status !== 'published') return // A new database is seeded with the current defaults.
  const doc = structuredClone(published)
  const applied = applyBrandRedesign(doc, direction)
  if (!applied) return
  await payload.updateGlobal({ slug: 'landing', data: { ...doc, _status: 'published' } as never, draft: false, depth: 0, req })
  payload.logger.info(`Brand redesign content migration (${direction}): updated ${applied} default fields.`)
}

export const up = (args: MigrateUpArgs) => migrate(args, 'up')
export const down = (args: MigrateDownArgs) => migrate(args as MigrateUpArgs, 'down')
